207	     */
208	    public Pet getPet(String name, boolean ignoreNew) {
209	        name = name.toLowerCase();
210	        for (Pet pet : getPetsInternal()) {
211	            if (!ignoreNew || !pet.isNew()) {
212	                String compName = pet.getName();
213	                compName = compName.toLowerCase();
214	                if (compName.equals(name)) {
215	                    return pet;
216	                }
