73	    }
74	
75	    @Override
76	    @Transactional(readOnly = true)
77	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
78	        return petRepository.findAll(pageable);
79	    }
80	
81	    @Override
82	    @Transactional
83	    public void deletePet(Pet pet) throws DataAccessException {
