211	    @Transactional(readOnly = true)
212	    public Pet findPetById(int id) throws DataAccessException {
213	        return findEntityById(() -> petRepository.findById(id));
214	    }
215	
216	    @Override
217	    @Transactional
218	    public void savePet(Pet pet) throws DataAccessException {
219	        pet.setType(findPetTypeById(pet.getType().getId()));
220	        petRepository.save(pet);
221	    }
222	
223	    @Override
224	    @Transactional
225	    public void saveVisit(Visit visit) throws DataAccessException {
226	        visitRepository.save(visit);
227	
228	    }
229	
230	    @Override
231	    @Transactional(readOnly = true)
232	    public Collection<Vet> findVets() throws DataAccessException {
233	        return vetRepository.findAll();
234	    }
235	
236	    @Override
237	    @Transactional
238	    public void saveOwner(Owner owner) throws DataAccessException {
239	        ownerRepository.save(owner);
240	
241	    }
242	
243	    @Override
244	    @Transactional(readOnly = true)
245	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
246	        return ownerRepository.findByLastName(lastName);
247	    }
248	
249	    @Override
250	    @Transactional(readOnly = true)
251	    public boolean isHouseholdInUse(String lastName, String address, Integer excludeId) throws DataAccessException {
252	        for (Owner existing : ownerRepository.findAll()) {
253	            if (excludeId != null && excludeId.equals(existing.getId())) {
254	                continue;
255	            }
256	            if (sameHousehold(lastName, address, existing)) {
257	                return true;
258	            }
259	        }
260	        return false;
261	    }
262	
263	    @Override
264	    @Transactional
265	    public void assignHousehold(Owner owner) throws DataAccessException {
266	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
267	        owner.setHouseholdId(householdId);
268	        for (Owner existing : ownerRepository.findAll()) {
269	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
270	                continue;
271	            }
272	            if (sameHousehold(owner.getLastName(), owner.getAddress(), existing)
273	                && !householdId.equals(existing.getHouseholdId())) {
274	                existing.setHouseholdId(householdId);
275	                ownerRepository.save(existing);
276	            }
277	        }
278	    }
279	
280	    /**
281	     * Whether {@code other} belongs to the same household as an owner with the given last name and
282	     * address, i.e. both match case-insensitively with collapsed whitespace. This single definition
283	     * of "same household" backs both {@link #isHouseholdInUse} and {@link #assignHousehold}.
284	     */
285	    private static boolean sameHousehold(String lastName, String address, Owner other) {
286	        return normalizeForHousehold(lastName).equals(normalizeForHousehold(other.getLastName()))
287	            && normalizeForHousehold(address).equals(normalizeForHousehold(other.getAddress()));
288	    }
289	
290	    /**
291	     * Normalizes a value for household comparison: leading/trailing whitespace is trimmed, internal
292	     * runs of whitespace are collapsed to a single space, and the result is lower-cased. This lets
293	     * two last names or addresses that differ only in case or whitespace be treated as equal.
294	     *
295	     * @param value the raw value, possibly {@code null}
296	     * @return the normalized comparison key, or {@code ""} when the value is {@code null}
297	     */
298	    private static String normalizeForHousehold(String value) {
299	        if (value == null) {
300	            return "";
301	        }
302	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
303	    }
304	
305	    /**
306	     * Derives the stable household identifier shared by all owners with the same last name and
307	     * address. The value is deterministic (the first 12 upper-case hex characters of the SHA-256
308	     * digest of the normalized last name and address), so every owner in the same household is
309	     * assigned an identical, non-blank identifier regardless of creation order.
310	     *
311	     * @param lastName the owner's last name
312	     * @param address  the owner's address
313	     * @return the stable household identifier
314	     */
315	    private static String householdIdFor(String lastName, String address) {
316	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
317	        try {
