319	                .digest(key.getBytes(StandardCharsets.UTF_8));
320	            StringBuilder sb = new StringBuilder(digest.length * 2);
321	            for (byte b : digest) {
322	                sb.append(String.format("%02X", b));
323	            }
324	            return sb.substring(0, 12);
325	        } catch (NoSuchAlgorithmException ex) {
326	            throw new IllegalStateException("SHA-256 not available", ex);
327	        }
328	    }
