59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
115	        owner.setTelephone(normalizedTelephone);
116	        owner.setEmail(normalizeEmail(owner.getEmail()));
117	        owner.setAddress(normalizeAddress(owner.getAddress()));
118	        validatePostcode(owner.getCity(), owner.getPostcode());
119	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
120	        if (effectiveRegistrationDate == null) {
121	            effectiveRegistrationDate = LocalDate.now();
122	        }
123	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
124	        owner.setRegistrationDate(effectiveRegistrationDate);
125	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
126	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
127	                "the maximum number of owners that may be created today has been reached");
128	        }
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        if (sharesHousehold) {
131	            this.clinicService.assignHousehold(owner);
132	        }
133	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                "an owner with the same identity already exists");
136	        }
137	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
138	            throw new ResponseStatusException(HttpStatus.CONFLICT,
139	                "city has reached its maximum number of owners");
140	        }
141	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
142	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        owner.setBulkSignupWarning(
145	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
146	        this.clinicService.saveOwner(owner);
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
149	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
150	            ownerDto.getMembershipLevel());
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
168	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
169	        this.clinicService.saveOwner(currentOwner);
170	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
